@@ -30,3 +38,29 @@ export function t(key, lang = "en", params = {}) {

 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/**
+ * The supported language a client asks for in an `Accept-Language` header
+ * (highest q-value wins, region tags such as `ko-KR` count as `ko`), or
+ * `fallback` when it names none of them.
+ */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  let best = null;
+  let bestQ = 0;
+  for (const part of String(header ?? "").split(",")) {
+    const [tag, ...attrs] = part.trim().split(";");
+    const lang = tag.trim().toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    let q = 1;
+    for (const attr of attrs) {
+      const m = /^\s*q\s*=\s*([0-9.]+)\s*$/i.exec(attr);
+      if (m) q = Number(m[1]);
+    }
+    if (!Number.isFinite(q) || q <= 0 || q > 1) continue;
+    if (q > bestQ) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
